// Cellphone ringer/vibrator control - one-shot triggering
module TopModule(
    input  ring,
    input  vibrate_mode,
    output reg ringer,
    output reg motor
);
    reg [1:0] state;
    parameter IDLE = 2'b00;
    parameter RINGING = 2'b01;
    parameter VIBRATING = 2'b10;
    always @(*) begin
        case(state)
            IDLE: begin
                if (ring) state = RINGING;
                else if (vibrate_mode) state = VIBRATING;
            end
            RINGING: begin
                ringer = 1;
                if (!ring) state = IDLE;
            end
            VIBRATING: begin
                motor = 1;
                if (!ring && !vibrate_mode) state = IDLE;
            end
        endcase
    end
    always @(posedge ring) state <= RINGING;
    always @(posedge vibrate_mode) state <= VIBRATING;
endmodule

